"""MANUS teleop start/stop/status service and ApexHand follow-topic routing."""

from __future__ import annotations

import threading
import time
from dataclasses import dataclass, field
from typing import Callable

import rclpy
from rcl_interfaces.msg import SetParametersResult
from rclpy.callback_groups import ReentrantCallbackGroup
from rclpy.clock import Clock, ClockType
from rclpy.node import Node
from rclpy.parameter import Parameter
from rclpy.qos import qos_profile_sensor_data
from sensor_msgs.msg import JointState

try:
    from manus_ros2_msgs.msg import ManusGlove
    from rysen_apexhand_msgs.srv import StartTeleop
except ImportError:  # pragma: no cover - allows syntax checks before msgs are built
    ManusGlove = None  # type: ignore
    StartTeleop = None  # type: ignore


DEFAULT_MANUS_TELEOP_SERVICE = "/rysen/apexhand/start_manus_teleop"
DEFAULT_GET_CONNECTION_INFO_SERVICE = "/rysen/apexhand/get_connection_info"
DEFAULT_FOLLOW_TOPIC_SUFFIX = "move_j_position_follow_command"
# Manager demuxes discovery-order /manus_glove_* into stable per-side feeds.
DEFAULT_ROUTED_GLOVE_TOPIC_LEFT = "/manus_teleop/glove_left"
DEFAULT_ROUTED_GLOVE_TOPIC_RIGHT = "/manus_teleop/glove_right"


def routed_glove_topic(side: str) -> str:
    """Stable glove topic for a retarget side (left/right)."""
    if side == "right":
        return DEFAULT_ROUTED_GLOVE_TOPIC_RIGHT
    return DEFAULT_ROUTED_GLOVE_TOPIC_LEFT


def ip_to_topic_key(ip: str) -> str:
    return "ip_" + ip.strip().replace(".", "_")


def resolve_follow_topic(ip: str, suffix: str = DEFAULT_FOLLOW_TOPIC_SUFFIX) -> str:
    return f"rysen/apexhand/{ip_to_topic_key(ip)}/{suffix.lstrip('/')}"


def normalize_side(side: str | None) -> str | None:
    if side is None:
        return None
    value = side.strip().lower()
    if value in ("left", "l", "lefthand", "handleft"):
        return "left"
    if value in ("right", "r", "righthand", "handright"):
        return "right"
    return None


@dataclass(frozen=True)
class ParsedTeleopCommand:
    """Parsed StartTeleop command: CODE:IP."""

    action: str  # start | stop | status | unknown
    code: str = ""
    ip: str | None = None
    side: str | None = None  # left | right for start
    opposition_enabled: bool | None = None
    error: str | None = None


COMMAND_HELP = (
    "格式为 CODE:IP，例如 1:192.168.0.103。"
    "支持: 0 停止, 5 状态, 1/2 左/右启动"
)


def parse_teleop_command(raw: str) -> ParsedTeleopCommand:
    """Parse ``CODE:IP`` teleop commands.

    Examples: ``0:192.168.0.103``, ``1:192.168.0.103``, ``2:192.168.0.104``.
    """
    token = (raw or "").strip()
    if not token:
        return ParsedTeleopCommand(
            action="unknown", error=f"空命令。{COMMAND_HELP}"
        )

    if ":" not in token:
        return ParsedTeleopCommand(
            action="unknown",
            code=token,
            error=f"缺少 IP，请使用 CODE:IP。{COMMAND_HELP}",
        )

    code_part, ip_part = token.split(":", 1)
    code = code_part.strip().lower()
    ip = ip_part.strip()
    if not ip:
        return ParsedTeleopCommand(
            action="unknown",
            code=code,
            error=f"IP 为空。{COMMAND_HELP}",
        )

    if code in ("0", "stop", "off"):
        return ParsedTeleopCommand(action="stop", code="0", ip=ip)
    if code in ("5", "status", "query", "state"):
        return ParsedTeleopCommand(action="status", code="5", ip=ip)
    if code in ("1", "left"):
        return ParsedTeleopCommand(
            action="start", code="1", ip=ip, side="left", opposition_enabled=True
        )
    if code in ("2", "right"):
        return ParsedTeleopCommand(
            action="start", code="2", ip=ip, side="right", opposition_enabled=True
        )
    return ParsedTeleopCommand(
        action="unknown",
        code=code,
        ip=ip,
        error=f"未知命令码 '{code}'。{COMMAND_HELP}",
    )


@dataclass
class ConnectedHand:
    ip: str
    side: str | None


@dataclass
class BoundSession:
    ip: str
    side: str  # left | right
    opposition_enabled: bool = True


@dataclass
class TeleopRuntimeState:
    active: bool = False
    opposition_enabled: bool = True
    requested_mode: str = "none"  # left|right|both|none from last start command
    glove_mode: str = "none"  # left|right|both|none from capture activity
    forwarding: bool = False
    connected_hands: list[ConnectedHand] = field(default_factory=list)
    bound_sessions: dict[str, BoundSession] = field(default_factory=dict)
    no_hand_streak: int = 0
    last_glove_stamp: dict[str, float] = field(default_factory=dict)


class ManusTeleopServiceMixin:
    """Mixin/helper attached to the retarget Node for StartTeleop + routing."""

    def init_manus_teleop_service(
        self: Node,
        *,
        on_state_changed: Callable[[TeleopRuntimeState], None] | None = None,
    ) -> None:
        self.declare_parameter("enable_teleop_service", False)
        self.declare_parameter("enable_follow_routing", True)
        self.declare_parameter("follow_routing_auto_start", False)
        self.declare_parameter("opposition_enabled", True)
        # Explicit IP bindings from manager / StartTeleop CODE:IP (comma-separated).
        self.declare_parameter("bound_apexhand_ips", [""])
        self.declare_parameter("bound_hand_sides", [""])
        self.declare_parameter(
            "teleop_service_name", DEFAULT_MANUS_TELEOP_SERVICE
        )
        self.declare_parameter(
            "get_connection_info_service",
            DEFAULT_GET_CONNECTION_INFO_SERVICE,
        )
        self.declare_parameter("follow_topic_suffix", DEFAULT_FOLLOW_TOPIC_SUFFIX)
        self.declare_parameter("glove_activity_timeout_sec", 0.5)
        self.declare_parameter("connection_poll_period_sec", 1.0)
        # 0 = never auto-stop based on get_connection_info (default: ignore hand link).
        self.declare_parameter("no_hand_auto_stop_count", 0)
        # When false (manager spawn), create follow pubs after glove match but do not
        # publish until manager arms after StartTeleop success checks.
        self.declare_parameter("follow_publish_armed", True)
        # Topics to watch for glove activity. Side (left/right) comes from
        # ManusGlove.side ("Left"/"Right"), NOT from topic index 0/1.
        self.declare_parameter(
            "glove_activity_topics",
            ["/manus_glove_0", "/manus_glove_1"],
        )
        # When owning StartTeleop, publishing starts only after command=1/2/3/11/...
        self.declare_parameter("require_teleop_service_start", True)

        own_service = bool(self.get_parameter("enable_teleop_service").value)
        follow_routing = bool(self.get_parameter("enable_follow_routing").value)
        auto_start = bool(self.get_parameter("follow_routing_auto_start").value)
        self._own_teleop_service = own_service
        self._follow_routing = follow_routing
        # Legacy publish path when neither service nor follow routing is used.
        self._teleop_enabled = own_service or follow_routing

        self._teleop_cb_group = ReentrantCallbackGroup()
        self._teleop_lock = threading.Lock()
        self._teleop_state = TeleopRuntimeState(
            active=bool(auto_start and follow_routing),
            opposition_enabled=bool(self.get_parameter("opposition_enabled").value),
        )
        self._apply_bound_session_params()
        self._teleop_on_state_changed = on_state_changed
        self._follow_pubs: dict[str, rclpy.publisher.Publisher] = {}
        self._conn_request_inflight = False
        self._follow_topic_suffix = str(
            self.get_parameter("follow_topic_suffix").value
        ).strip() or DEFAULT_FOLLOW_TOPIC_SUFFIX
        self._glove_activity_timeout_sec = float(
            self.get_parameter("glove_activity_timeout_sec").value
        )
        self._no_hand_auto_stop_count = int(
            self.get_parameter("no_hand_auto_stop_count").value
        )
        self._follow_publish_armed = bool(
            self.get_parameter("follow_publish_armed").value
        )
        self._require_service_start = bool(
            self.get_parameter("require_teleop_service_start").value
        )
        self._stamp_clock = Clock(clock_type=ClockType.SYSTEM_TIME)

        if not self._teleop_enabled:
            self.get_logger().info(
                "MANUS teleop service/routing disabled; using legacy publish path if enabled."
            )
            return

        if own_service and StartTeleop is None:
            self.get_logger().error(
                "rysen_apexhand_msgs StartTeleop unavailable; service disabled."
            )
            self._own_teleop_service = False

        # Follow routing is driven only by CODE:IP bindings — do not gate on
        # get_connection_info / whether an ApexHand is already linked.
        self._conn_client = None

        if self._own_teleop_service:
            service_name = str(self.get_parameter("teleop_service_name").value).strip()
            self._teleop_srv = self.create_service(
                StartTeleop,
                service_name,
                self._on_start_teleop,
                callback_group=self._teleop_cb_group,
            )
            self.get_logger().info(f"MANUS teleop service ready at {service_name}")
        else:
            self.get_logger().info(
                "MANUS StartTeleop not owned by this node "
                "(expected external manager)."
            )

        activity_topics = [
            str(t).strip()
            for t in self.get_parameter("glove_activity_topics").value
            if str(t).strip()
        ]
        if self.has_parameter("glove_topic"):
            primary = str(self.get_parameter("glove_topic").value).strip()
            if primary and primary not in activity_topics:
                activity_topics.append(primary)
            # Manager-spawned child already binds one raw topic; extra 0/1
            # subscriptions only add callback load on the IK GIL.
            if follow_routing and not own_service and primary:
                activity_topics = [primary]

        if ManusGlove is None:
            self.get_logger().warn(
                "manus_ros2_msgs unavailable; glove activity side detection limited "
                "to the primary glove_topic callback (uses ManusGlove.side)."
            )
        else:
            for topic in activity_topics:
                self.create_subscription(
                    ManusGlove,
                    topic,
                    self._on_glove_activity,
                    qos_profile_sensor_data,
                    callback_group=self._teleop_cb_group,
                )
            self.get_logger().info(
                "Glove activity topics (side from ManusGlove.side): "
                + (", ".join(activity_topics) if activity_topics else "(none)")
            )

        self.add_on_set_parameters_callback(self._on_follow_arm_param)

        # Do not create follow pubs yet — only after matching glove side is seen.
        self._glove_forward_timer = self.create_timer(
            0.1,
            self._on_glove_forward_timer,
            callback_group=self._teleop_cb_group,
        )
        self._rebuild_forwarding()

        if self._teleop_state.active:
            self.get_logger().info(
                "Follow routing auto-started from bound sessions; "
                "will publish only after matching glove side is confirmed "
                "(ignores ApexHand link state)."
            )

        self.get_logger().info(
            f"Follow routing enabled (suffix: {self._follow_topic_suffix}); "
            "forwarding starts only when ManusGlove.side matches the bound session."
        )

    # --- public API used by IK loop ---

    def teleop_should_publish(self) -> bool:
        if not getattr(self, "_teleop_enabled", False):
            return True  # legacy path: caller decides via publish_apexhand_commands
        with self._teleop_lock:
            self._refresh_glove_mode_locked(time.monotonic())
            armed = bool(self._follow_publish_armed)
            return (
                armed
                and self._teleop_state.active
                and self._teleop_state.forwarding
                and bool(self._follow_pubs)
            )

    def teleop_opposition_enabled(self) -> bool:
        if not getattr(self, "_teleop_enabled", False):
            if self.has_parameter("opposition_enabled"):
                return bool(self.get_parameter("opposition_enabled").value)
            return True
        with self._teleop_lock:
            return self._teleop_state.opposition_enabled

    def teleop_publish_joint_command(self, msg: JointState) -> int:
        """Publish only after armed + matching glove side. Returns publisher count."""
        if not getattr(self, "_teleop_enabled", False):
            return 0
        with self._teleop_lock:
            if not self._follow_publish_armed:
                return 0
            self._refresh_glove_mode_locked(time.monotonic())
            if not (self._teleop_state.active and self._teleop_state.forwarding):
                return 0
            glove_mode = self._teleop_state.glove_mode
            sessions = dict(self._teleop_state.bound_sessions)
            pubs = dict(self._follow_pubs)
        if glove_mode == "none" or not pubs:
            return 0
        n = 0
        for ip, pub in pubs.items():
            session = sessions.get(ip)
            if session is None:
                continue
            if glove_mode != "both" and session.side != glove_mode:
                continue
            if not rclpy.ok():
                break
            try:
                pub.publish(msg)
            except rclpy.exceptions.RCLError:
                # Shutdown race: context already torn down (e.g. Ctrl+C).
                break
            n += 1
        return n

    def _on_follow_arm_param(self, params: list[Parameter]) -> SetParametersResult:
        for param in params:
            if param.name != "follow_publish_armed":
                continue
            armed = bool(param.value)
            self._follow_publish_armed = armed
            if armed:
                self.get_logger().info(
                    "Follow publish ARMED — creating follow topics and enabling publish"
                )
            else:
                self.get_logger().info(
                    "Follow publish DISARMED — destroying follow topics / holding"
                )
            # Create or tear down follow publishers only when arm state changes.
            self._rebuild_forwarding()
        return SetParametersResult(successful=True)

    def teleop_note_glove_side(self, side: str | None) -> None:
        norm = normalize_side(side)
        if norm is None:
            return
        now = time.monotonic()
        with self._teleop_lock:
            self._teleop_state.last_glove_stamp[norm] = now
            self._refresh_glove_mode_locked(now)
        # Do not rebuild publishers here — glove arrives at ~100 Hz and would
        # contend with the IK loop. Pubs are created on arm / bind changes.

    def _on_glove_forward_timer(self) -> None:
        """Refresh live glove mode; drop pubs only if bindings/arming changed."""
        if not getattr(self, "_teleop_enabled", False):
            return
        with self._teleop_lock:
            if not self._teleop_state.active:
                return
            self._refresh_glove_mode_locked(time.monotonic())
            armed = bool(self._follow_publish_armed)
            n_sessions = len(self._teleop_state.bound_sessions)
        # Recreate/clear pubs only when they cannot match current bind/arm state.
        if (armed and n_sessions and not self._follow_pubs) or (
            (not armed or not n_sessions) and self._follow_pubs
        ):
            self._rebuild_forwarding()

    # --- callbacks ---

    def _on_glove_activity(self, msg) -> None:
        # Side is carried by the message itself (Manus SDK: "Left" / "Right").
        # Topic names like manus_glove_0/1 are NOT left/right bindings.
        side = normalize_side(getattr(msg, "side", None))
        if side is None:
            return
        self.teleop_note_glove_side(side)

    def _on_start_teleop(self, request, response):
        parsed = parse_teleop_command(request.command)
        if parsed.action == "unknown":
            response.success = False
            response.message = parsed.error or (
                f"未知命令 '{request.command}'。{COMMAND_HELP}"
            )
            return response

        assert parsed.ip is not None

        if parsed.action == "status":
            response.success = True
            response.message = self._format_status_message(ip=parsed.ip)
            return response

        if parsed.action == "stop":
            self._unbind_session(parsed.ip, reason="服务停止")
            response.success = True
            response.message = self._format_status_message(
                ip=parsed.ip, human=f"已停止 IP={parsed.ip}"
            )
            return response

        # start
        assert parsed.side is not None
        with self._teleop_lock:
            self._teleop_state.active = True
            self._teleop_state.opposition_enabled = bool(parsed.opposition_enabled)
            self._teleop_state.requested_mode = parsed.side
            self._teleop_state.bound_sessions[parsed.ip] = BoundSession(
                ip=parsed.ip,
                side=parsed.side,
                opposition_enabled=bool(parsed.opposition_enabled),
            )
            self._teleop_state.no_hand_streak = 0
            self._refresh_glove_mode_locked(time.monotonic())
        self._rebuild_forwarding()
        opp_txt = "全功能(含对指)" if parsed.opposition_enabled else "无对指"
        response.success = True
        response.message = self._format_status_message(
            ip=parsed.ip,
            human=f"已绑定 {parsed.side} -> {parsed.ip} ({opp_txt})",
        )
        self.get_logger().info(
            f"MANUS teleop started: command={request.command!r} "
            f"side={parsed.side} ip={parsed.ip} opposition={parsed.opposition_enabled}"
        )
        return response

    def _apply_bound_session_params(self) -> None:
        """Load bound IP/side lists passed by the manager into runtime state."""
        ips = [
            str(v).strip()
            for v in self.get_parameter("bound_apexhand_ips").value
            if str(v).strip()
        ]
        sides_raw = [
            str(v).strip()
            for v in self.get_parameter("bound_hand_sides").value
        ]
        if not ips:
            return
        opposition = bool(self.get_parameter("opposition_enabled").value)
        sessions: dict[str, BoundSession] = {}
        for i, ip in enumerate(ips):
            side = normalize_side(sides_raw[i] if i < len(sides_raw) else None) or "left"
            sessions[ip] = BoundSession(
                ip=ip, side=side, opposition_enabled=opposition
            )
        with self._teleop_lock:
            self._teleop_state.bound_sessions = sessions
            if sessions:
                self._teleop_state.active = True
                sides = {s.side for s in sessions.values()}
                if sides == {"left", "right"}:
                    self._teleop_state.requested_mode = "both"
                else:
                    self._teleop_state.requested_mode = next(iter(sides))
        self.get_logger().info(
            "Bound ApexHand sessions: "
            + ", ".join(f"{s.side}->{s.ip}" for s in sessions.values())
        )
    # --- helpers ---

    def _unbind_session(self, ip: str, *, reason: str) -> None:
        with self._teleop_lock:
            removed = self._teleop_state.bound_sessions.pop(ip, None)
            remaining = len(self._teleop_state.bound_sessions)
            if remaining == 0:
                self._teleop_state.active = False
                self._teleop_state.forwarding = False
                self._teleop_state.no_hand_streak = 0
        self._rebuild_forwarding()
        if removed is None:
            self.get_logger().info(f"停止请求 IP={ip}（未绑定）: {reason}")
        elif remaining == 0:
            self.get_logger().info(f"MANUS teleop fully stopped ({ip}): {reason}")
        else:
            self.get_logger().info(
                f"Unbound IP={ip} side={removed.side}; remaining={remaining}"
            )

    def _refresh_glove_mode_locked(self, now: float) -> None:
        timeout = self._glove_activity_timeout_sec
        left = (now - self._teleop_state.last_glove_stamp.get("left", 0.0)) <= timeout
        right = (now - self._teleop_state.last_glove_stamp.get("right", 0.0)) <= timeout
        if left and right:
            mode = "both"
        elif left:
            mode = "left"
        elif right:
            mode = "right"
        else:
            mode = "none"
        self._teleop_state.glove_mode = mode

    def _rebuild_forwarding(self) -> None:
        """Create follow publishers only after armed (StartTeleop success).

        Detection phase keeps armed=false → no follow topic, no publish.
        After manager arms, advertise bound follow topics; publish still requires
        matching live glove side in teleop_publish_joint_command.
        """
        with self._teleop_lock:
            active = self._teleop_state.active
            glove_mode = self._teleop_state.glove_mode
            sessions = dict(self._teleop_state.bound_sessions)
            armed = bool(self._follow_publish_armed)

        if not active or not sessions or not armed:
            had = bool(self._follow_pubs)
            self._clear_follow_pubs()
            with self._teleop_lock:
                self._teleop_state.forwarding = False
            if had and not armed:
                self.get_logger().info(
                    "Follow topics cleared (not armed — waiting for StartTeleop success)"
                )
            return

        # Armed: create pubs for every bound session (manager already verified glove).
        # Live glove mismatch still blocks publish in teleop_publish_joint_command.
        wanted = dict(sessions)

        current_ips = set(self._follow_pubs)
        for ip in current_ips - set(wanted):
            self._follow_pubs.pop(ip, None)
            self.get_logger().info(f"转发已停止: IP={ip}")
        for ip, session in wanted.items():
            if ip in self._follow_pubs:
                continue
            topic = resolve_follow_topic(ip, self._follow_topic_suffix)
            self._follow_pubs[ip] = self.create_publisher(JointState, topic, 10)
            self.get_logger().info(
                f"转发已建立: bound {session.side} -> {topic} "
                f"(armed, glove_mode={glove_mode})"
            )

        forwarding = len(self._follow_pubs) > 0
        with self._teleop_lock:
            self._teleop_state.forwarding = forwarding
        if self._teleop_on_state_changed is not None:
            with self._teleop_lock:
                snapshot = TeleopRuntimeState(**self._teleop_state.__dict__)
            self._teleop_on_state_changed(snapshot)

    def _clear_follow_pubs(self) -> None:
        self._follow_pubs.clear()

    def _stop_teleop(self, reason: str) -> None:
        with self._teleop_lock:
            self._teleop_state.active = False
            self._teleop_state.forwarding = False
            self._teleop_state.no_hand_streak = 0
            self._teleop_state.bound_sessions.clear()
        self._clear_follow_pubs()
        self.get_logger().info(f"MANUS teleop stopped: {reason}")

    def _format_status_message(
        self, human: str | None = None, *, ip: str | None = None
    ) -> str:
        with self._teleop_lock:
            sessions = dict(self._teleop_state.bound_sessions)
            active = self._teleop_state.active and bool(sessions)
            forwarding = self._teleop_state.forwarding
            exo_mode = self._teleop_state.glove_mode
            opposition = self._teleop_state.opposition_enabled
            session = sessions.get(ip) if ip else None

        if ip is not None:
            bound = session is not None
            side = session.side if session else "none"
            opp = (
                ("含对指" if session.opposition_enabled else "无对指")
                if session
                else "-"
            )
            if human is None:
                if not bound:
                    human = f"IP={ip} 未绑定"
                elif not forwarding or ip not in getattr(self, "_follow_pubs", {}):
                    human = f"IP={ip} 已绑定 side={side}({opp})，等待转发"
                else:
                    human = f"IP={ip} 遥操作中 side={side}({opp})"
            return (
                f"active={'true' if bound else 'false'} "
                f"forwarding={'true' if (bound and ip in getattr(self, '_follow_pubs', {})) else 'false'} "
                f"exo_mode={side}; {human}"
            )

        if human is None:
            if not active:
                human = "遥操作未启动"
            elif not forwarding:
                if exo_mode == "none":
                    human = "遥操作运行中，手套模式未检测，等待建立转发"
                else:
                    human = (
                        f"遥操作运行中，手套模式={exo_mode}，等待建立转发"
                    )
            else:
                opp = "含对指" if opposition else "无对指"
                binds = ",".join(f"{s.side}->{s.ip}" for s in sessions.values())
                human = (
                    f"遥操作运行中，手套模式={exo_mode}，转发已建立({opp}) [{binds}]"
                )
        return (
            f"active={'true' if active else 'false'} "
            f"forwarding={'true' if forwarding else 'false'} "
            f"exo_mode={exo_mode}; {human}"
        )
